userscript.function:

doServiceAjax('sepoa.svc.seal.SepoaSealManagementService', 'CONNECTION', 'doDocumentDetail', {
    DOC_NO: docNo,
    MANAGE_NUMBER: manageNo,
    APPLY_TYPE: "RE",
    COMPANY_CODE: companyCode
}, function(so) {
    if (so.status == 1) {
        var soResult = new SepoaFormater(so.result[0]);
        formObj.dataMapper(soResult);
        var status = soResult.getArrayMap()[0].STATUS;
        if (status) {
            setModeByStatus(status);
        } else {
            Alert(Sepoa.cache.text.get('SLM_153.MESSAGE006'), function() { //문서의 상태를 확인할 수 없습니다.
                doBack();
            });
        }
        return true;
    } else {
        Alert(Sepoa.cache.text.get('MESSAGE.1002'));
        doBack();
        return false;
    }
});


if (formObj.getValue('SUBJECT') == "") {
    Alert(Sepoa.cache.text.get("SLM_153.MESSAGE001")); //인감을 선택해주세요.
    return;
}

var params = {};

var serviceData = {
    parameter: {
        basic_info: getCustomFormData()
    }
};

params.SEAL_DATA = JSON.stringify(serviceData);
params.CURRENT_PRC = 'CREATE';

if (callbackObj) {
    doServiceAjax('sepoa.svc.seal.SepoaSealManagementService', 'TRANSACTION', 'doReturnService', params, function(so) {
        if (so.status == 1) {
            callbackObj.CALLBACK(callbackObj.CALLBACK_PARMETER);
        } else {
            Alert(so.message);
        }
    });
} else {
    Confirm(Sepoa.cache.text.get('SLM_153.MESSAGE002'), function(flag) { //저장하시겠습니까?
        if (flag) {
            doServiceAjax('sepoa.svc.seal.SepoaSealManagementService', 'TRANSACTION', 'doReturnService', params, function(so) {
                if (so.status == 1) {
                    Alert(Sepoa.cache.text.get("MESSAGE.0001"));
                } else {
                    Alert(so.message);
                }
            });
        }
    });
}


var basic_info = getCustomFormData();
basic_info.LEGAL_PRC_TYPE = callbackParams.LEGAL_PRC_TYPE;
basic_info.ACCEPT_REASON = callbackParams.ACCEPT_REASON;

var serviceData = {
    parameter: {
        basic_info: basic_info
    }
};

var params = {
    CURRENT_PRC: 'LEGAL',
    SEAL_DATA: JSON.stringify(serviceData)
}

doServiceAjax('sepoa.svc.seal.SepoaSealManagementService', 'TRANSACTION', 'doReturnService', params, function(so) {
    if (so.status == 1) {
        if (Sepoa.request.MODE == 'NEW') {
            SUX.root.getContentsCell(window).close();
        } else {
            doBack(callbackParams);
        }
        Alert(Sepoa.cache.text.get("MESSAGE.0001"));
    } else {
        Alert(so.message);
    }
});


if (formObj.getValue('SUBJECT') == "") {
    Alert(Sepoa.cache.text.get('SLM_153.MESSAGE001')); //인감을 선택해주세요.
    return;
}

if (!formObj.validate()) {
    Alert(Sepoa.cache.text.get("MESSAGE.0002")); //VALIDATION
    return;
}

Confirm(Sepoa.cache.text.get('SLM_153.MESSAGE003'), function(flag) { //인감 반납 승인요청을 하시겠습니까?
    if (flag) {
        doSave({
            CALLBACK: doLegalProcess,
            CALLBACK_PARMETER: {
                LEGAL_PRC_TYPE: "LEGAL_REQUEST"
            }
        })
    }
})


Confirm(Sepoa.cache.text.get('SLM_153.MESSAGE004'), function(flag) { //승인하시겠습니까?
    if (flag) {
    	popupReason({
    		title: Sepoa.cache.text.get('SLM_211.CONFIRM_REASON'),
    		callbackFn: doLegalAcceptAfterReason,
    		mode: "WRITE"
    	});
    }
});


        	doSave({
        		CALLBACK: doLegalProcess,
        		CALLBACK_PARMETER: {
					LEGAL_PRC_TYPE: "LEGAL_ACCEPT",
					ACCEPT_REASON: obj.APP_COMMENT
				}
		    });

		    return true;


Confirm(Sepoa.cache.text.get('SLM_153.MESSAGE005'), function(flag) { //반려하시겠습니까?
    if (flag) {
    	popupReason({
    		title: Sepoa.cache.text.get('SLM_211.REJECT_REASON'),
    		callbackFn: doLegalRejectAfterReason,
    		mode: "REJECT"
    	});
    }
});


        	doSave({
        		CALLBACK: doLegalProcess,
        		CALLBACK_PARMETER: {
					LEGAL_PRC_TYPE: "LEGAL_REJECT",
					ACCEPT_REASON: obj.APP_COMMENT
				}
		    });

		    return true;


        	sUtils.popup.modal({
		        url: '/UxDefault/Common/WindowForm.sux',
		        title: data.title,
		        header: true,
		        params: {
		            mode: data.mode,
		            form: 'APP_COMMENT',
		    		callback: data.callbackFn || function() {}
		    	}
		    })


        	//중간단계 없이 바로 분실처리
            if (formObj.getValue('SUBJECT') == "") {
                Alert(Sepoa.cache.text.get("SLM_153.MESSAGE001")); //인감을 선택해주세요.
                return;
            }

            if (!formObj.validate()) {
                Alert(Sepoa.cache.text.get("MESSAGE.0002")); //VALIDATION
                return;
            }

            var params = {};

            var serviceData = {
                parameter: {
                    basic_info: getCustomFormData()
                }
            };

            params.SEAL_DATA = JSON.stringify(serviceData);
            params.CURRENT_PRC = 'CREATE';
            params.NEXT_PRC = 'COMPLETE';

            Confirm(Sepoa.cache.text.get('SLM_153.MESSAGE007'), function(flag) { //반납처리 하시겠습니까?
                if (flag) {
                    doServiceAjax('sepoa.svc.seal.SepoaSealManagementService', 'TRANSACTION', 'doReturnService', params, function(so) {
                        if (so.status == 1) {
			                if (Sepoa.request.MODE == 'NEW') {
			                	SUX.root.getContentsCell(window).close();
			                } else {
			                	doBack();
			                }
			                Alert(Sepoa.cache.text.get("MESSAGE.0001"));
                        } else {
                            Alert(so.message);
                        }
                    });
                }
            });


switch (name) {
    case "SAVE":
        doSave();
        break;
    case "BACK":
        doBack();
        break;
    case "LEGAL_REQUEST":
        doLegalRequest();
        break;
    case "LEGAL_ACCEPT":
        doAccept();
        break;
    case "LEGAL_REJECT":
        doReject();
        break;
    case "SELECT_SEAL_BTN":
        doOpenSealPopup();
        break;
    case "APP_REQUEST":
    	doApprovalRequest();
    	break;
    case "RETURN":
        doReturn();
        break;                    
    default:
        break;
}


switch (status) {
    case "NEW":
        setNewMode();
        break;
    case "T":
        setEditMode();
        break;
    case "G":
        setReadMode();
        break;
    case "O":
        setReadMode()
        break;
    case "N":
        setReadMode()
        break;
    case "C":
        setReadMode();
        break;
    case "DETAIL":
        break;
    default:
        break;
}
setBtns(status);


hideAllBtn();
switch (status) {
    case "NEW":
        //btnObj.btn('SAVE').setShow();

        if (sUtils.workflow.check('SR1635987653344')) { //결재 모듈
            btnObj.btn('APP_REQUEST').setShow();
            return;
        }

        if (sUtils.workflow.check('SR1635987653583')) { //법무팀 승인 모듈
            btnObj.btn('LEGAL_REQUEST').setShow();
            return;
        }

        if (sUtils.workflow.check('SR1635987653854')) { //완료 모듈
			btnObj.btn('RETURN').setShow();
        }

        break;
    case "T":
        btnObj.btn('BACK').setShow();
        //btnObj.btn('SAVE').setShow();

        if (sUtils.workflow.check('SR1635987653344')) { //결재 모듈
            btnObj.btn('APP_REQUEST').setShow();
            return;
        }

        if (sUtils.workflow.check('SR1635987653583')) { //법무팀 승인 모듈
            btnObj.btn('LEGAL_REQUEST').setShow();
            return;
        }

        if (sUtils.workflow.check('SR1635987653854')) { //완료 모듈
			btnObj.btn('RETURN').setShow();
        }

        break;
    case "G":
        if (Sepoa.info.CTRL_CODE.indexOf('MANAGE_CONFIRM') > -1) {
            btnObj.btn('LEGAL_ACCEPT').setShow();
            btnObj.btn('LEGAL_REJECT').setShow();
        }
        btnObj.btn('BACK').setShow();
        break;
    case "O":
        btnObj.btn('BACK').setShow();
        break;
    case "N":
        btnObj.btn('BACK').setShow();
        break;
    case "C":
        btnObj.btn('BACK').setShow();
        break;
    case "DETAIL":
        break;
    default:
        break;
}


	var width = SUX.root.innerWidth * 0.85;
    var height = SUX.root.innerHeight * 0.85;
    var params = {
        MODE: 'POPUP',
        WORK_TYPE: 'RETURN'
    }
    PopupOpenPost('/Seal/Manage/SealManageSelectPopupLayoyt.sux', params, setSeal, '', height, Sepoa.cache.text.get('SLM_143.POPUP_TITLE'));


var manageNumber = data.MANAGE_NUMBER;

//인감에 대한 정보 조회
doServiceAjax('sepoa.svc.seal.SepoaSealManagementService', 'CONNECTION', 'doSealDetail', {
    MANAGE_NUMBER: manageNumber,
}, function(so) {
    if (so.status == 1) {
        var soResult = new SepoaFormater(so.result[0]);
        doSealDataMapping(soResult);
        return true;
    } else {
        Alert(Sepoa.cache.text.get('MESSAGE.1002'));
        return false;
    }
});


var sealData = soResult.getArrayMap()[0];
formObj.setValue("SUBJECT", sealData.SUBJECT);
formObj.setValue("SEAL_TYPE", sealData.SEAL_TYPE);
formObj.setValue("MANAGE_NUMBER", sealData.MANAGE_NUMBER);
formObj.setValue("SEAL_DATE", sealData.SEAL_DATE);
formObj.setValue("SEAL_MG_USER_NAME", sealData.SEAL_MG_USER_NAME);
formObj.setValue("SEAL_MG_DEPT_NAME", sealData.SEAL_MG_DEPT_NAME);


btnObj.forEachBtn(function(id) {
    btnObj.btn(id).setHide();
})


$share.data = {};
var docNo = getDocumentNumber("SLD");
$share.data.DOC_NO = docNo;
formObj.setValue("DOC_NO", docNo);


var g = formObj.getFormData();
for (var formName in g) {
    formObj.setReadOnly(formName, true);
}

var formBtnArr = ['SELECT_SEAL_BTN'];
formBtnArr.forEach(function(btn) {
    formObj.setdisable(btn, true);
});


var g = formObj.getFormData();
for (var formName in g) {
    formObj.setReadOnly(formName, false);
}

var defaultReadOnlyItem = ['SUBJECT', 'SEAL_TYPE', 'SEAL_MG_USER_NAME', 'SEAL_MG_DEPT_NAME',
    'MANAGE_NUMBER', 'SEAL_DATE'
];

defaultReadOnlyItem.forEach(function(item) {
    formObj.setReadOnly(item, true);
})

var formBtnArr = ['SELECT_SEAL_BTN'];
formBtnArr.forEach(function(btn) {
    formObj.setdisable(btn, false);
});


var data = formObj.getFormData();
data.SEAL_DATE = formObj.getValue('SEAL_DATE');
return data;


if (!formObj.validate()) {
    Alert(Sepoa.cache.text.get('MESSAGE.0002'));
    return;
}

Confirm(Sepoa.cache.text.get('SLM_153.MESSAGE_APPROVAL_REQUEST'), function(flag) {
    if (flag) {
        doSave({
            CALLBACK: doSetApproval,
            CALLBACK_PARMETER: {
                APPROVAL_PRC_TYPE: "APPROVAL_REQUEST"
            }
        });
    }
});


var params = {};
params.data = [{
    APP_LINE_SEQ: '0',
    APP_METHOD: '01',
    APP_USER_ID: Sepoa.info.ID,
    APP_USER_NAME: Sepoa.info.NAME_LOC,
    SELLER_CODE: Sepoa.info.COMPANY_CODE,
    POSITION: Sepoa.info.POSITION,
    DEPARTMENT_NAME: Sepoa.info.DEPARTMENT_NAME_LOC,
    EMPLOYEE_NO: Sepoa.info.EMPLOYEE_NO
}];

var width = Math.min(SUX.root.innerWidth * 0.7, 1280);
var height = Math.min((SUX.root.innerHeight - 100) * 0.9, 800);
PopupOpenPost('/UxDefault/ApprovalLine/Popup.sux', params, function(data) {
    var params = {};
    params.data = data;
    params.callbackParams = callbackParams;

    doApprovalProcess(params);
}, width, height, Sepoa.cache.text.get('SLM_211.APPLINE_SETTING'));


var config = {
    url: window.CONTEXT_NAME + '/SepoaActionController.sux',
    on: {
        callback: function(res) {
            if (res.status == "1") {
                Alert(Sepoa.cache.text.get('MESSAGE.0001'));
                if (Sepoa.request.SMR_NUMBER) {
                    doQuery(Sepoa.request.SMR_NUMBER);
                } else if (smrStatus == 'T' && moveFlag == 'Y') {
                    linkTo('SLM_170', '/Seal/Manage/SealManageRequestCarousel.sux', 'undefined', Sepoa.cache.text.get('SLM_170.TITLE'));
                    SUX.root.getContentsCell(window).close();
                } else {
                    doBack();
                }
            } else {
                Alert(res.message);
            }
        }
    }
}

var basic_info = getCustomFormData();
basic_info.MANAGE_DOC_NO = $share.data.MANAGE_NUMBER + '_' + $share.data.DOC_NO;

var app_type = 'J08';

var serviceData = {
    parameter: {
        basic_info: basic_info,
        APP_TYPE: app_type,
		APP_LINE: params.data.approver,
    	APP_INFO: {
        	APP_COMMENT: params.data.comment
    	}
    }
};

var params = {
    module: "seal.management",
    action: "doReturnService",
    CONNECTION: "TRANSACTION",
    CURRENT_PRC: 'APPROVAL',
    SEAL_DATA: JSON.stringify(serviceData)
}

sUtils.multipart.send(config, params);
